javascript:(async()=>{
  const esperar=(ms)=>new Promise((resolve)=>setTimeout(resolve,ms));

  const recopilarTextoCompleto=async()=>{
    const textos=new Set();
    const guardarTexto=()=>{
      for(const linea of document.body.innerText.split('\n')){
        const limpia=linea.trim();
        if(limpia) textos.add(limpia);
      }
    };
    const contenedores=[document.scrollingElement,...document.querySelectorAll('*')]
      .filter((elemento,index,lista)=>elemento&&lista.indexOf(elemento)===index)
      .filter((elemento)=>{
        const estilo=getComputedStyle(elemento);
        return elemento.scrollHeight>elemento.clientHeight&&/(auto|scroll)/.test(estilo.overflowY);
      });
    guardarTexto();
    for(const contenedor of contenedores){
      const posicionOriginal=contenedor.scrollTop;
      const salto=Math.max(300,Math.floor(contenedor.clientHeight*0.8));
      for(let posicion=0;posicion<contenedor.scrollHeight;posicion+=salto){
        contenedor.scrollTop=posicion;
        await esperar(150);
        guardarTexto();
      }
      contenedor.scrollTop=contenedor.scrollHeight;
      await esperar(150);
      guardarTexto();
      contenedor.scrollTop=posicionOriginal;
    }
    return Array.from(textos).join('\n');
  };

  const texto=await recopilarTextoCompleto();
  const jira=(texto.match(/\bFTR-\d+\b/)||['JIRA_NO_ENCONTRADO'])[0];
  const lineas=texto.split('\n').map((x)=>x.trim());
  const regexFecha=/^\d{2}\.\d{2}\.\d{4}\b/;
  const regexImporte=/^(?:\d{1,3}(?:\.\d{3})+|\d+),\d{2}$/;
  const regexMoneda=/^[A-Z]{3}$/;
  const resultado=[];
  let enActividad=false;
  let comentarios=0;

  const parseImporte=(valor)=>Number(valor.replace(/\./g,'').replace(',','.'));
  const formatImporte=(valor)=>new Intl.NumberFormat('es-ES',{
    minimumFractionDigits:2,
    maximumFractionDigits:2
  }).format(valor);

  const extraerImporteYMoneda=(linea)=>{
    const tokens=linea.split(/\s+/).filter(Boolean);
    for(let i=0;i<tokens.length;i++){
      const actual=tokens[i];
      const previo=tokens[i-1];
      const siguiente=tokens[i+1];
      if(regexMoneda.test(actual)&&previo&&regexImporte.test(previo)){
        return {moneda:actual,importe:parseImporte(previo)};
      }
      if(regexImporte.test(actual)&&siguiente&&regexMoneda.test(siguiente)){
        return {moneda:siguiente,importe:parseImporte(actual)};
      }
    }
    return null;
  };

  const cerrarModalExistente=()=>{
    const previo=document.getElementById('__copiar_jira_resumen__');
    if(previo) previo.remove();
  };

  const bancos=[
    {nombre:'Sabadell',prefijo:'BSD'},
    {nombre:'Santander',prefijo:'BCH'},
    {nombre:'BBVA',prefijo:'BBV'}
  ];

  const bancoDeCodigo=(codigo)=>{
    const limpio=(codigo||'').trim().toUpperCase();
    const banco=bancos.find((b)=>limpio.startsWith(b.prefijo));
    return banco?banco.nombre:null;
  };

  const lanzarFiesta=()=>{
    const idEstilo='__copiar_jira_fiesta_estilo__';
    let estilo=document.getElementById(idEstilo);
    if(!estilo){
      estilo=document.createElement('style');
      estilo.id=idEstilo;
      estilo.textContent=`
        @keyframes __lluviaBilletes__ {
          0% { transform: translate3d(0,-120px,0) rotate(0deg); opacity: 0; }
          10% { opacity: 1; }
          100% { transform: translate3d(var(--deriva),calc(100vh + 160px),0) rotate(var(--giro)); opacity: .9; }
        }
      `;
      document.head.appendChild(estilo);
    }

    const capa=document.createElement('div');
    capa.style.position='fixed';
    capa.style.inset='0';
    capa.style.overflow='hidden';
    capa.style.pointerEvents='none';
    capa.style.zIndex='2147483647';
    document.body.appendChild(capa);

    const billetesFiesta=[{'denominacion': '100', 'src': 'data:image/webp;base64,'}, {'denominacion': '50', 'src': 'data:image/webp;base64,'}, {'denominacion': '20', 'src': 'data:image/webp;base64,'}, {'denominacion': '10', 'src': 'data:image/webp;base64,'}];
    for(let i=0;i<100;i++){
      const modelo=billetesFiesta[Math.floor(Math.random()*billetesFiesta.length)];
      const billete=document.createElement('div');
      const imagen=document.createElement('img');
      imagen.src=modelo.src;
      imagen.alt='';
      imagen.draggable=false;
      imagen.style.display='block';
      imagen.style.width='100%';
      imagen.style.height='auto';
      imagen.style.borderRadius='2px';
      billete.appendChild(imagen);
      if(modelo.denominacion==='10'){
        const marca=document.createElement('span');
        marca.textContent='10';
        Object.assign(marca.style,{position:'absolute',right:'4px',top:'3px',padding:'0 3px',borderRadius:'2px',background:'rgba(122,18,18,.90)',color:'#fff7ed',font:'700 10px Georgia,serif',lineHeight:'14px',boxShadow:'0 1px 3px rgba(0,0,0,.3)'});
        billete.appendChild(marca);
      }
      billete.style.position='absolute';
      billete.style.left=`${Math.random()*100}vw`;
      billete.style.top=`-${110+Math.random()*90}px`;
      billete.style.width=`${58+Math.random()*42}px`;
      billete.style.height='auto';
      billete.style.pointerEvents='none';
      billete.style.userSelect='none';
      billete.style.borderRadius='2px';
      billete.style.boxShadow='0 4px 9px rgba(15,23,42,.25)';
      billete.style.filter='saturate(.94) contrast(1.03) drop-shadow(0 3px 2px rgba(15,23,42,.16))';
      billete.style.setProperty('--deriva',`${-100+Math.random()*200}px`);
      billete.style.setProperty('--giro',`${240+Math.random()*720}deg`);
      billete.style.animation=`__lluviaBilletes__ ${5.5+Math.random()*4}s linear ${Math.random()*.8}s forwards`;
      capa.appendChild(billete);
    }
    setTimeout(()=>capa.remove(),11000);
  };

  const mostrarResumen=(movimientos,resumenEstado)=>{
    cerrarModalExistente();
    let resumenTexto='';
    const disponibles=bancos.filter((b)=>movimientos.some((m)=>m.banco===b.nombre));
    const activos=new Set(disponibles.map((b)=>b.nombre));

    const overlay=document.createElement('div');
    overlay.id='__copiar_jira_resumen__';
    Object.assign(overlay.style,{position:'fixed',inset:'0',background:'rgba(15,23,42,0.35)',display:'flex',alignItems:'center',justifyContent:'center',padding:'24px',zIndex:'2147483646'});

    const modal=document.createElement('div');
    Object.assign(modal.style,{background:'#ffffff',color:'#0f172a',width:'100%',maxWidth:'520px',borderRadius:'14px',boxShadow:'0 25px 70px rgba(15,23,42,0.28)',border:'1px solid rgba(148,163,184,0.35)',padding:'24px',fontFamily:'Segoe UI, sans-serif'});

    const titulo=document.createElement('h2');
    titulo.textContent='Resumen por moneda';
    Object.assign(titulo.style,{margin:'0 0 16px',fontSize:'22px'});
    modal.appendChild(titulo);

    const filtros=document.createElement('div');
    Object.assign(filtros.style,{display:'flex',gap:'8px',marginBottom:'16px',flexWrap:'wrap'});
    const botonesBanco=new Map();
    for(const banco of disponibles){
      const boton=document.createElement('button');
      boton.type='button';
      boton.textContent=banco.nombre;
      Object.assign(boton.style,{borderRadius:'999px',padding:'7px 14px',fontWeight:'600',fontSize:'13px',cursor:'pointer'});
      boton.addEventListener('click',()=>{
        if(activos.has(banco.nombre)) activos.delete(banco.nombre);
        else activos.add(banco.nombre);
        render();
      });
      botonesBanco.set(banco.nombre,boton);
      filtros.appendChild(boton);
    }
    if(disponibles.length) modal.appendChild(filtros);

    const contenedorTabla=document.createElement('div');
    modal.appendChild(contenedorTabla);

    const estado=document.createElement('p');
    estado.textContent=resumenEstado;
    Object.assign(estado.style,{margin:'0 0 18px',fontSize:'13px',lineHeight:'1.5',color:'#64748b'});
    modal.appendChild(estado);

    const acciones=document.createElement('div');
    Object.assign(acciones.style,{display:'flex',alignItems:'center',gap:'10px'});

    const botonFiesta=document.createElement('button');
    botonFiesta.type='button';
    botonFiesta.textContent='Fiesta!';
    Object.assign(botonFiesta.style,{border:'0',borderRadius:'10px',padding:'10px 14px',fontWeight:'700',cursor:'pointer',background:'#0f766e',color:'#ffffff',marginRight:'auto'});
    botonFiesta.addEventListener('click',lanzarFiesta);

    const botonCopiar=document.createElement('button');
    botonCopiar.type='button';
    botonCopiar.textContent='Copiar resumen';
    Object.assign(botonCopiar.style,{border:'0',borderRadius:'10px',padding:'10px 14px',fontWeight:'600'});
    botonCopiar.addEventListener('click',async()=>{
      if(!resumenTexto) return;
      await navigator.clipboard.writeText(resumenTexto);
      const textoOriginal=botonCopiar.textContent;
      botonCopiar.textContent='Resumen copiado';
      setTimeout(()=>{botonCopiar.textContent=textoOriginal;},1200);
    });

    const cerrar=()=>{
      document.removeEventListener('keydown',onKeyDown);
      overlay.remove();
    };
    const onKeyDown=(event)=>{if(event.key==='Escape') cerrar();};

    const botonCerrar=document.createElement('button');
    botonCerrar.type='button';
    botonCerrar.textContent='Cerrar';
    Object.assign(botonCerrar.style,{border:'1px solid #cbd5e1',borderRadius:'10px',padding:'10px 14px',fontWeight:'600',cursor:'pointer',background:'#ffffff',color:'#0f172a'});
    botonCerrar.addEventListener('click',cerrar);
    overlay.addEventListener('click',(event)=>{if(event.target===overlay) cerrar();});

    acciones.appendChild(botonFiesta);
    acciones.appendChild(botonCopiar);
    acciones.appendChild(botonCerrar);
    modal.appendChild(acciones);

    const render=()=>{
      const sinFiltro=activos.size===0||activos.size===disponibles.length;
      for(const [nombre,boton] of botonesBanco){
        const on=activos.has(nombre);
        boton.style.border=on?'1px solid #0f766e':'1px solid #cbd5e1';
        boton.style.background=on?'#0f766e':'#ffffff';
        boton.style.color=on?'#ffffff':'#475569';
      }

      const totales=new Map();
      for(const mov of movimientos){
        if(!sinFiltro&&!activos.has(mov.banco)) continue;
        totales.set(mov.moneda,(totales.get(mov.moneda)||0)+mov.importe);
      }

      const filas=Array.from(totales.entries())
        .sort(([a],[b])=>a.localeCompare(b))
        .map(([moneda,total])=>({moneda,total:formatImporte(total)}));
      const nombresActivos=disponibles.filter((b)=>activos.has(b.nombre)).map((b)=>b.nombre);
      const encabezado=sinFiltro?'Total de pagos:':`Pagos ${nombresActivos.join(' y ')}`;
      resumenTexto=filas.length?`${encabezado}\n${filas.map((fila)=>`${fila.moneda}\t${fila.total}`).join('\n')}`:'';

      contenedorTabla.textContent='';
      if(filas.length){
        const tabla=document.createElement('table');
        Object.assign(tabla.style,{width:'100%',borderCollapse:'collapse',marginBottom:'18px'});
        tabla.innerHTML='<thead><tr><th style="text-align:left;padding:0 0 10px;border-bottom:1px solid #cbd5e1;">Moneda</th><th style="text-align:right;padding:0 0 10px;border-bottom:1px solid #cbd5e1;">Total</th></tr></thead>';
        const cuerpo=document.createElement('tbody');
        for(const fila of filas){
          const tr=document.createElement('tr');
          tr.innerHTML=`<td style="padding:10px 0;border-bottom:1px solid #e2e8f0;font-weight:600;">${fila.moneda}</td><td style="padding:10px 0;border-bottom:1px solid #e2e8f0;text-align:right;font-variant-numeric:tabular-nums;">${fila.total}</td>`;
          cuerpo.appendChild(tr);
        }
        tabla.appendChild(cuerpo);
        contenedorTabla.appendChild(tabla);
      }else{
        const vacio=document.createElement('p');
        vacio.textContent='No se detectaron importes y monedas válidos para el filtro actual.';
        vacio.style.margin='0 0 18px';
        contenedorTabla.appendChild(vacio);
      }

      botonCopiar.disabled=!resumenTexto;
      botonCopiar.style.cursor=resumenTexto?'pointer':'not-allowed';
      botonCopiar.style.background=resumenTexto?'#0f766e':'#cbd5e1';
      botonCopiar.style.color=resumenTexto?'#ffffff':'#475569';
    };

    render();
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
    document.addEventListener('keydown',onKeyDown);
  };

  for(const l of lineas){
    if(l==='Actividad') enActividad=true;
    if(regexFecha.test(l)){
      resultado.push(l);
      if(enActividad) comentarios++;
    }
  }

  if(!resultado.length){
    alert('No se encontraron líneas con fecha dd.mm.aaaa');
    return;
  }

  const salida=`### JIRA: ${jira}\n${resultado.join('\n')}`;
  await navigator.clipboard.writeText(salida);

  const movimientos=[];
  for(const linea of resultado){
    const extraido=extraerImporteYMoneda(linea);
    if(!extraido) continue;
    movimientos.push({...extraido,banco:bancoDeCodigo(linea.split('\t')[5])});
  }

  const resumenEstado=`Copiadas ${resultado.length} líneas. ${comentarios>0?`Detectadas ${comentarios} líneas en comentarios.`:'Sin movimientos en comentarios.'}`;
  mostrarResumen(movimientos,resumenEstado);
})();
